    INSERT INTO src.tenants (tenant_id, tenant_slug, tenant_name, plan, cloud_region, status, account_tier, seats, signup_date, last_modified) SELECT tenant_id, tenant_slug, tenant_name, plan, cloud_region, status, account_tier, seats, signup_date, last_modified FROM src.stage_tenants WHERE release_day = @day;
    INSERT INTO src.support_tickets (ticket_id, tenant_id, ticket_type, priority, status, opened_ts, solved_ts, credit_aud, agent_hours, description, last_modified) SELECT ticket_id, tenant_id, ticket_type, priority, status, opened_ts, solved_ts, credit_aud, agent_hours, description, last_modified FROM src.stage_support_tickets WHERE release_day = @day;
