/* Lyrebird Apps (Digital natives) - source database seed for the pipeline Copy demo
   Plays the role of: Product database (Azure SQL / PostgreSQL)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.tenants; DROP TABLE IF EXISTS src.support_tickets; DROP TABLE IF EXISTS src.stage_tenants; DROP TABLE IF EXISTS src.stage_support_tickets;
CREATE TABLE src.tenants (tenant_id INT NOT NULL, tenant_slug NVARCHAR(30), tenant_name NVARCHAR(100), plan NVARCHAR(30), cloud_region NVARCHAR(40), status NVARCHAR(30), account_tier INT, seats DECIMAL(12,1), signup_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_tenants PRIMARY KEY (tenant_id));
CREATE TABLE src.support_tickets (ticket_id INT NOT NULL, tenant_id INT, ticket_type NVARCHAR(30), priority INT, status NVARCHAR(30), opened_ts DATETIME2(0), solved_ts DATETIME2(0), credit_aud DECIMAL(12,2), agent_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_support_tickets PRIMARY KEY (ticket_id));
CREATE TABLE src.stage_tenants (release_day INT NOT NULL, tenant_id INT, tenant_slug NVARCHAR(30), tenant_name NVARCHAR(100), plan NVARCHAR(30), cloud_region NVARCHAR(40), status NVARCHAR(30), account_tier INT, seats DECIMAL(12,1), signup_date DATE, last_modified DATETIME2(0), success_manager NVARCHAR(50));
CREATE TABLE src.stage_support_tickets (release_day INT NOT NULL, ticket_id INT, tenant_id INT, ticket_type NVARCHAR(30), priority INT, status NVARCHAR(30), opened_ts DATETIME2(0), solved_ts DATETIME2(0), credit_aud DECIMAL(12,2), agent_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.tenants', 'success_manager') IS NULL
        EXEC('ALTER TABLE src.tenants ADD success_manager NVARCHAR(50) NULL');
    DELETE t FROM src.tenants t WHERE EXISTS (SELECT 1 FROM src.stage_tenants s WHERE s.release_day = @day AND s.tenant_id = t.tenant_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.success_manager = s.success_manager FROM src.tenants t JOIN src.stage_tenants s ON s.tenant_id = t.tenant_id AND s.release_day = 3');
    DELETE t FROM src.support_tickets t WHERE EXISTS (SELECT 1 FROM src.stage_support_tickets s WHERE s.release_day = @day AND s.ticket_id = t.ticket_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.tenants) AS tenants, (SELECT COUNT(*) FROM src.support_tickets) AS support_tickets;
END;
GO
